record.field:
drafts = records.filtered(lambda m: m.state == 'draft' and m.move_type == 'in_invoice')
for move in drafts:
    try:
        move.action_run_ocr()
        env.cr.commit()
    except Exception as e:
        env['ir.logging'].sudo().create({
            'name': 'account_invoice_ocr_ai',
            'type': 'server',
            'level': 'WARNING',
            'message': 'Bulk OCR failed for move %s: %s' % (move.id, e),
            'path': 'action_run_ocr_server',
            'func': 'bulk',
            'line': '0',
        })
        env.cr.rollback()
